"use client";

import { useState, type HTMLAttributes, type ImgHTMLAttributes } from "react";

export function Avatar({ className = "", ...props }: HTMLAttributes<HTMLSpanElement>) { return <span className={`co-relative co-flex co-size-10 co-shrink-0 co-overflow-hidden co-rounded-full co-bg-black/10 ${className}`.trim()} {...props} />; }
export function AvatarImage({ className = "", onError, ...props }: ImgHTMLAttributes<HTMLImageElement>) {
  const [failed, setFailed] = useState(false);
  if (failed) return null;
  return <img className={`co-size-full co-object-cover ${className}`.trim()} onError={(event) => { setFailed(true); onError?.(event); }} {...props} />;
}
export function AvatarFallback({ className = "", ...props }: HTMLAttributes<HTMLSpanElement>) { return <span className={`co-flex co-size-full co-items-center co-justify-center co-text-sm co-font-medium ${className}`.trim()} {...props} />; }
